/* ============ WV TOOLTIP + HEADER ============ */
.wv-sync-tip {
  display: inline-flex; align-items: center; margin-left: 4px;
  cursor: help; opacity: 0.7; transition: opacity 0.2s ease;
}
.wv-sync-tip:hover { opacity: 1; }
.wv-sync-tip img { display: block; }
#wvPanel .panel-head {
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 8px; width: 100%; overflow-x: hidden;
}
#wvPanel { overflow-x: hidden; width: 100%; padding: 0 12px; }
#wvPanel .panel-head__title {
  display: inline-flex; align-items: center; gap: 8px; margin: 0;
}
#wvPanel .panel-head,
#wvPanel .wv-season,
#wvPanel .tabs { padding-left: 12px; padding-right: 12px; }

/* ============ BOTONES DE NAV WV ============ */
#wvTabBtnObjDashboard, #wvTabBtnPurchaseDetail,
#wvTabBtnRefreshDashboard, #wvTabBtnBackToWV, #wvTabBtnSyncObjectives {
  display: inline-flex !important;
}
#wvTabBtnObjDashboard[hidden], #wvTabBtnPurchaseDetail[hidden],
#wvTabBtnRefreshDashboard[hidden], #wvTabBtnBackToWV[hidden], #wvTabBtnSyncObjectives[hidden] {
  display: none !important;
}

/* ============ WVPD TOOLBAR ============ */
.wvpd-iconbtn {
  background: none !important; border: none !important; padding: 0 !important;
  margin: 0 0 0 auto !important; width: auto !important; height: auto !important;
  display: inline-flex !important; align-items: center; justify-content: center; cursor: pointer;
}
.wvpd-iconbtn img {
  width: 40px !important; height: 40px !important; display: block !important;
  border-radius: 8px !important; box-shadow: none !important;
  background: transparent !important; pointer-events: none;
}
.wvpd-iconbtn:hover img { filter: brightness(1.08); }
.wvpd-number--amber { color:#ffd36b !important; font-weight:700; }
.wvpd-number--red { color:#ff9d9d !important; font-weight:700; }
.wvpd-green { color:#a0ffc8 !important; font-weight:700; }
.wvpd-label--red { color:#ff9d9d !important; }
#wvpdUsefulContent .wvpd-li > :last-child { color:#ffd36b !important; font-weight:700; }
#wvpdTopAccounts .wvpd-li .wvpd-li__delta { color:#ff9d9d !important; font-weight:700; }
#wvpdTopItems .wvpd-li .wvpd-li__rest { color:#ffd36b !important; font-weight:700; }
#wvPDPanel .wvpd-banner__icon img { width: 50px !important; height: 50px !important; }
#wvPDPanel .wvpd-banner__icon {
  width: 56px !important; height: 56px !important;
  display: inline-flex !important; align-items: center; justify-content: center;
}

